mapper.sql:
SELECT o.id, o.customer_name, o.order_no, o.order_date, o.receivable_date, o.order_total, COALESCE(dlv.delivered_amount, 0) as delivered_amount, COALESCE(rcv.received_amount, 0) as received_amount, COALESCE(dlv.delivered_amount, 0) - COALESCE(rcv.received_amount, 0) as outstanding, CASE WHEN o.receivable_date IS NOT NULL AND COALESCE(dlv.delivered_amount, 0) - COALESCE(rcv.received_amount, 0) > 0 THEN DATEDIFF(CURDATE(), o.receivable_date) ELSE NULL END as overdue_days FROM mis_sales_order o LEFT JOIN ( SELECT source_order_id, SUM(delivery_amount) as delivered_amount FROM mis_delivery WHERE del_flag = '0' GROUP BY source_order_id ) dlv ON o.id = dlv.source_order_id LEFT JOIN ( SELECT rd.sales_order_id, SUM(rd.receipt_amount) as received_amount FROM mis_receipt_order_detail rd JOIN mis_receipt_order r ON rd.receipt_id = r.id WHERE rd.del_flag = '0' AND r.del_flag = '0' AND r.status = '1' GROUP BY rd.sales_order_id ) rcv ON o.id = rcv.sales_order_id WHERE o.del_flag = '0'
AND o.customer_name LIKE CONCAT('%', #{params.customerName}, '%')
AND o.order_no LIKE CONCAT('%', #{params.orderNo}, '%')
AND o.order_date >= #{params.beginDate}
AND o.order_date <= #{params.endDate}
